import React from "react";
import {
  AbsoluteFill,
  interpolate,
  interpolateColors,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily } = loadSpaceGrotesk();



export type TerminalTradingChartProps = Record<string, any>;

const TerminalTradingChart: React.FC<TerminalTradingChartProps> = ({
  backgroundColor = "#080b0e",
  transparentBackground = false,
  durationInSeconds = 8,
  accentColorUp = "#26a69a",
  accentColorDown = "#ef5350",
  accentColorEntry = "#ffd54f",
  title = "FOMO Trading Cycle",
  caption = "Entered too late. Punished by the retracement.",
  strongMoveLabel = "Strong move up",
  fomoLabel = "FOMO Buy — enters late",
  stopLossLabel = "Stop Loss",
  reversalLabel = "Price continues without you.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  // Frame segments mapping
  const p1Start = 0;
  const p1End = totalFrames * 0.22;

  const p2Start = p1End;
  const p2End = totalFrames * 0.35;

  const p3Start = p2End;
  const p3End = totalFrames * 0.55;

  const p4Start = p3End;
  const p4End = totalFrames * 0.70;

  const p5Start = p4End;
  const p5End = totalFrames * 0.90;

  const p6Start = p5End;
  const p6End = totalFrames;

  // Normalized progresses
  const p1Progress = interpolate(frame, [p1Start, p1End], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const p2Progress = interpolate(frame, [p2Start, p2End], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const p3Progress = interpolate(frame, [p3Start, p3End], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const p4Progress = interpolate(frame, [p4Start, p4End], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const p5Progress = interpolate(frame, [p5Start, p5End], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const p6Progress = interpolate(frame, [p6Start, p6End], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Spring animations for UI pops
  const p2Spring = spring({
    frame: frame - p2Start,
    fps,
    config: { damping: 12, mass: 0.5 },
  });

  const stoppedOutScale = spring({
    frame: frame - p4Start,
    fps,
    config: { damping: 10, mass: 0.6, stiffness: 120 },
  });

  // Background and Flash behaviors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  const flashActive = frame >= p4Start && frame <= p5End;
  const flashPhase = Math.floor((frame - p4Start) / 4) % 2 === 0;
  const stopColor = flashActive 
    ? (flashPhase ? "#ffffff" : accentColorDown)
    : accentColorDown;
  const stopTextShadow = flashActive && flashPhase
    ? `0 0 12px ${accentColorDown}`
    : "none";

  // Determine currently active phase indicator step
  let currentActiveStep = 1;
  if (frame >= p5Start) {
    currentActiveStep = 5;
  } else if (frame >= p4Start) {
    currentActiveStep = 4;
  } else if (frame >= p3Start) {
    currentActiveStep = 3;
  } else if (frame >= p2Start) {
    currentActiveStep = 2;
  } else {
    currentActiveStep = 1;
  }

  // Steps indicator configuration
  const steps = [
    {
      num: 1,
      title: "STRONG MOVE UP",
      subtitle: "Bullish impulse",
      color: accentColorUp,
    },
    {
      num: 2,
      title: "FOMO ENTRY",
      subtitle: "Enters late",
      color: accentColorEntry,
    },
    {
      num: 3,
      title: "SHARP RETRACEMENT",
      subtitle: "Price pulls back",
      color: accentColorDown,
    },
    {
      num: 4,
      title: "STOP HIT",
      subtitle: "Stopped out",
      color: accentColorDown,
    },
    {
      num: 5,
      title: "PRICE CONTINUES",
      subtitle: "Without you",
      color: accentColorUp,
    },
  ];

  // Candlesticks pre-generation
  const candles = React.useMemo(() => {
    const result = [];
    
    // Phase 1: Upward trend (25 candles)
    // Starts around y = 78%, ends around y = 30%
    const numP1 = 25;
    for (let i = 0; i < numP1; i++) {
      const progress = i / (numP1 - 1);
      const baseVal = 78 - progress * 48; // 78 down to 30
      const wave = Math.sin(i * 0.8) * 2.5;
      const open = baseVal + wave + (i % 2 === 0 ? 1.5 : -1.5);
      const close = baseVal + wave - (i % 2 === 0 ? 2 : -2);
      
      const isGreen = close < open;
      const high = Math.min(open, close) - (1.0 + Math.abs(Math.sin(i) * 1.5));
      const low = Math.max(open, close) + (1.0 + Math.abs(Math.cos(i) * 1.5));
      
      result.push({
        id: `p1-${i}`,
        phase: 1,
        x: 3 + progress * 36.5, // 3% to 39.5%
        open,
        close,
        high,
        low,
        isGreen: i % 5 !== 0, // Mostly green
      });
    }

    // Phase 3: Sharp Retracement (18 candles)
    // Starts at peak (y = 30%) and falls to y = 82%
    const numP3 = 18;
    const startX = 39.5;
    const endX = 64.5;
    for (let i = 0; i < numP3; i++) {
      const progress = i / (numP3 - 1);
      const baseVal = 30 + progress * 52; // 30 to 82
      const wave = Math.sin(i * 1.2) * 2;
      const open = baseVal + wave - (i % 3 === 0 ? 1.5 : -1.5);
      const close = baseVal + wave + (i % 3 === 0 ? 3 : 1.5);
      
      const isGreen = close < open;
      const high = Math.min(open, close) - (1.0 + Math.abs(Math.sin(i) * 1.0));
      const low = Math.max(open, close) + (1.0 + Math.abs(Math.cos(i) * 1.0));
      
      result.push({
        id: `p3-${i}`,
        phase: 3,
        x: startX + progress * (endX - startX),
        open,
        close,
        high,
        low,
        isGreen: i % 4 === 0, // Mostly red
      });
    }

    // Phase 5: Reversal and continuation (24 candles)
    // Starts around y = 82% and goes up to y = 14%
    const numP5 = 24;
    const startXP5 = 64.5;
    const endXP5 = 97;
    for (let i = 0; i < numP5; i++) {
      const progress = i / (numP5 - 1);
      const baseVal = 82 - progress * 68; // 82 to 14
      const wave = Math.sin(i * 0.9) * 2;
      const open = baseVal + wave + (i % 2 === 0 ? 1.5 : -1.5);
      const close = baseVal + wave - (i % 2 === 0 ? 2.5 : -2);
      
      const isGreen = close < open;
      const high = Math.min(open, close) - (1.0 + Math.abs(Math.sin(i) * 1.5));
      const low = Math.max(open, close) + (1.0 + Math.abs(Math.cos(i) * 1.5));
      
      result.push({
        id: `p5-${i}`,
        phase: 5,
        x: startXP5 + progress * (endXP5 - startXP5),
        open,
        close,
        high,
        low,
        isGreen: i % 5 !== 0, // Bullish reversal
      });
    }

    return result;
  }, []);

  // Dimensions of central chart
  const chartW = width * 0.9;
  const chartH = height * 0.72;
  const chartLeft = width * 0.05;
  const chartTop = height * 0.14;

  const toX = (pct: number) => (pct / 100) * chartW;
  const toY = (pct: number) => (pct / 100) * chartH;

  // Custom vector arrows calculations
  // Phase 1 Arrow
  const x1_p1 = toX(12);
  const y1_p1 = toY(65);
  const x2_p1 = toX(33);
  const y2_p1 = toY(44);
  const arrowP1 = interpolate(p1Progress, [0.3, 0.95], [0, 1], { extrapolateRight: "clamp" });
  const cx2_p1 = x1_p1 + (x2_p1 - x1_p1) * arrowP1;
  const cy2_p1 = y1_p1 + (y2_p1 - y1_p1) * arrowP1;
  const angle_p1 = Math.atan2(y2_p1 - y1_p1, x2_p1 - x1_p1);

  // FOMO Entry Arrow
  const x1_p2 = toX(34.5);
  const y1_p2 = toY(18);
  const x2_p2 = toX(38.0);
  const y2_p2 = toY(26.5);
  const arrowP2 = p2Progress; 
  const cx2_p2 = x1_p2 + (x2_p2 - x1_p2) * arrowP2;
  const cy2_p2 = y1_p2 + (y2_p2 - y1_p2) * arrowP2;
  const angle_p2 = Math.atan2(y2_p2 - y1_p2, x2_p2 - x1_p2);

  // Reversal Arrow
  const x1_p5 = toX(68);
  const y1_p5 = toY(70);
  const x2_p5 = toX(93);
  const y2_p5 = toY(26);
  const arrowP5 = interpolate(p5Progress, [0.3, 0.95], [0, 1], { extrapolateRight: "clamp" });
  const cx2_p5 = x1_p5 + (x2_p5 - x1_p5) * arrowP5;
  const cy2_p5 = y1_p5 + (y2_p5 - y1_p5) * arrowP5;
  const angle_p5 = Math.atan2(y2_p5 - y1_p5, x2_p5 - x1_p5);

  // Stop loss line evolution
  const stopLineProgress = interpolate(p3Progress, [0.1, 0.7], [0, 1], { extrapolateRight: "clamp" });
  const lineStartX = toX(3);
  const lineEndX = toX(3) + (toX(97) - toX(3)) * stopLineProgress;
  const lineY = toY(78);

  const leftPillVisible = stopLineProgress > 0.05;
  const rightPillVisible = stopLineProgress > 0.85;

  // Custom arrow head renderer
  const renderArrowHead = (x: number, y: number, angle: number, size: number, color: string) => {
    const p1X = x - size * Math.cos(angle - Math.PI / 6);
    const p1Y = y - size * Math.sin(angle - Math.PI / 6);
    const p2X = x - size * Math.cos(angle + Math.PI / 6);
    const p2Y = y - size * Math.sin(angle + Math.PI / 6);
    return (
      <polygon
        points={`${x},${y} ${p1X},${p1Y} ${p2X},${p2Y}`}
        fill={color}
      />
    );
  };

  // Process caption styling (highlight the second part)
  const captionParts = caption.split(". ");
  const firstCaptionPart = captionParts[0] ? `${captionParts[0]}.` : "";
  const secondCaptionPart = captionParts[1] || "";

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        background: `radial-gradient(circle at 50% 50%, #111822 0%, ${bgColor} 100%)`,
        fontFamily,
        overflow: "hidden",
      }}
    >
      {/* Top Bar Steps Indicator */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          width: "100%",
          padding: `${height * 0.03}px ${width * 0.05}px`,
          backgroundColor: "rgba(8, 11, 14, 0.85)",
          borderBottom: "1px solid rgba(255, 255, 255, 0.05)",
          zIndex: 10,
          boxSizing: "border-box",
        }}
      >
        {steps.map((step, idx) => {
          const isCompleted = currentActiveStep > step.num;
          const isActive = currentActiveStep === step.num;
          const isPending = currentActiveStep < step.num;
          
          let stepOpacity = 0.35;
          if (isActive) stepOpacity = 1;
          if (isCompleted) stepOpacity = 0.75;

          const numBgColor = isCompleted || isActive ? step.color : "#1a222a";
          const numTextColor = isCompleted || isActive ? "#080b0e" : "#8c9ba5";

          return (
            <React.Fragment key={step.num}>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  opacity: stepOpacity,
                  transform: `scale(${isActive ? 1.03 : 1})`,
                  transition: "all 0.2s ease",
                }}
              >
                {/* Step Circle */}
                <div
                  style={{
                    width: `${Math.min(width, height) * 0.032}px`,
                    height: `${Math.min(width, height) * 0.032}px`,
                    borderRadius: "50%",
                    backgroundColor: numBgColor,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    color: numTextColor,
                    fontWeight: "bold",
                    fontSize: `${Math.min(width, height) * 0.016}px`,
                    marginRight: "10px",
                    boxShadow: isActive ? `0 0 15px ${step.color}88` : "none",
                    border: isPending ? "1px solid rgba(255,255,255,0.1)" : "none",
                  }}
                >
                  {step.num}
                </div>
                {/* Step Label */}
                <div style={{ display: "flex", flexDirection: "column" }}>
                  <span
                    style={{
                      color: isActive ? "#ffffff" : "#c5d0db",
                      fontWeight: isActive ? "bold" : "600",
                      fontSize: `${Math.min(width, height) * 0.013}px`,
                      letterSpacing: "0.5px",
                    }}
                  >
                    {step.title}
                  </span>
                  <span
                    style={{
                      color: "#6c7a84",
                      fontSize: `${Math.min(width, height) * 0.011}px`,
                      marginTop: "2px",
                    }}
                  >
                    {step.subtitle}
                  </span>
                </div>
              </div>
              {idx < steps.length - 1 && (
                <svg
                  width="12"
                  height="18"
                  viewBox="0 0 12 18"
                  fill="none"
                  style={{ opacity: 0.25, flexShrink: 0, margin: "0 10px" }}
                >
                  <path
                    d="M 2 2 L 10 9 L 2 16"
                    stroke="#ffffff"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              )}
            </React.Fragment>
          );
        })}
      </div>

      {/* Main Terminal Chart Container */}
      <div
        style={{
          position: "absolute",
          left: `${chartLeft}px`,
          top: `${chartTop}px`,
          width: `${chartW}px`,
          height: `${chartH}px`,
          backgroundColor: "rgba(10, 14, 18, 0.4)",
          border: "1px solid rgba(255,255,255,0.03)",
          borderRadius: "8px",
          transition: "none",
        }}
      >
        {/* Custom Dot-Grid Backdrop */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            backgroundImage: "radial-gradient(circle, rgba(255, 255, 255, 0.04) 1px, transparent 1.5px)",
            backgroundSize: "28px 28px",
            zIndex: 1,
          }}
        />

        {/* Technical Coordinate lines */}
        {[20, 40, 60, 80].map((val) => (
          <div
            key={`h-${val}`}
            style={{
              position: "absolute",
              top: `${val}%`,
              left: 0,
              right: 0,
              height: "1px",
              borderTop: "1px dashed rgba(255, 255, 255, 0.025)",
              zIndex: 1,
            }}
          />
        ))}

        {[15, 30, 45, 60, 75, 90].map((val) => (
          <div
            key={`v-${val}`}
            style={{
              position: "absolute",
              left: `${val}%`,
              top: 0,
              bottom: 0,
              width: "1px",
              borderLeft: "1px dashed rgba(255, 255, 255, 0.025)",
              zIndex: 1,
            }}
          />
        ))}

        {/* Dynamic Candlesticks Rendering */}
        {candles.map((candle, idx) => {
          let visible = false;
          let revealProgress = 0;

          if (candle.phase === 1) {
            const currentRevealIndex = p1Progress * 25;
            if (idx <= currentRevealIndex) {
              visible = true;
              revealProgress = interpolate(currentRevealIndex - idx, [0, 1], [0, 1], {
                extrapolateRight: "clamp",
              });
            }
          } else if (candle.phase === 3) {
            const currentRevealIndex = p3Progress * 18;
            const p3Index = idx - 25; // Index offset for Phase 3
            if (p3Index <= currentRevealIndex) {
              visible = true;
              revealProgress = interpolate(currentRevealIndex - p3Index, [0, 1], [0, 1], {
                extrapolateRight: "clamp",
              });
            }
          } else if (candle.phase === 5) {
            const currentRevealIndex = p5Progress * 24;
            const p5Index = idx - 25 - 18; // Index offset for Phase 5
            if (p5Index <= currentRevealIndex) {
              visible = true;
              revealProgress = interpolate(currentRevealIndex - p5Index, [0, 1], [0, 1], {
                extrapolateRight: "clamp",
              });
            }
          }

          if (!visible) return null;

          const candleColor = candle.isGreen ? accentColorUp : accentColorDown;
          const bodyY = Math.min(candle.open, candle.close);
          const bodyHeight = Math.max(0.6, Math.abs(candle.open - candle.close));

          // Animate entry height scaling
          const animatedScaleY = interpolate(revealProgress, [0, 1], [0.1, 1]);
          const animatedOpacity = interpolate(revealProgress, [0, 1], [0, 1]);

          return (
            <div
              key={candle.id}
              style={{
                position: "absolute",
                left: `${candle.x}%`,
                top: 0,
                width: "1.0%",
                height: "100%",
                transform: `translateX(-50%)`,
                zIndex: 2,
                opacity: animatedOpacity,
                transition: "none",
              }}
            >
              {/* Wick */}
              <div
                style={{
                  position: "absolute",
                  left: "calc(50% - 1px)",
                  top: `${candle.high}%`,
                  height: `${candle.low - candle.high}%`,
                  width: "2px",
                  backgroundColor: candleColor,
                  opacity: 0.65,
                }}
              />

              {/* Body */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  right: 0,
                  top: `${bodyY}%`,
                  height: `${bodyHeight}%`,
                  backgroundColor: candleColor,
                  borderRadius: "1px",
                  boxShadow: candle.isGreen 
                    ? `0 0 8px ${accentColorUp}25` 
                    : `0 0 8px ${accentColorDown}25`,
                  transform: `scaleY(${animatedScaleY})`,
                  transformOrigin: "center",
                }}
              />
            </div>
          );
        })}

        {/* Vector SVG Annotations Overlay */}
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            pointerEvents: "none",
            zIndex: 3,
          }}
        >
          {/* Phase 1 Green Arrow ("Strong move up") */}
          {arrowP1 > 0 && (
            <>
              <line
                x1={x1_p1}
                y1={y1_p1}
                x2={cx2_p1}
                y2={cy2_p1}
                stroke={accentColorUp}
                strokeWidth={3}
                strokeLinecap="round"
              />
              {renderArrowHead(cx2_p1, cy2_p1, angle_p1, 12, accentColorUp)}
            </>
          )}

          {/* Phase 2 FOMO Entry Yellow Arrow */}
          {arrowP2 > 0 && (
            <>
              <line
                x1={x1_p2}
                y1={y1_p2}
                x2={cx2_p2}
                y2={cy2_p2}
                stroke={accentColorEntry}
                strokeWidth={3}
                strokeLinecap="round"
              />
              {renderArrowHead(cx2_p2, cy2_p2, angle_p2, 11, accentColorEntry)}
            </>
          )}

          {/* Stop-Loss Dashed Red Line */}
          {stopLineProgress > 0 && (
            <line
              x1={lineStartX}
              y1={lineY}
              x2={lineEndX}
              y2={lineY}
              stroke={stopColor}
              strokeWidth={2}
              strokeDasharray="8 6"
              style={{ transition: "none" }}
            />
          )}

          {/* Phase 5 Reversal Green Arrow */}
          {arrowP5 > 0 && (
            <>
              <line
                x1={x1_p5}
                y1={y1_p5}
                x2={cx2_p5}
                y2={cy2_p5}
                stroke={accentColorUp}
                strokeWidth={3}
                strokeLinecap="round"
              />
              {renderArrowHead(cx2_p5, cy2_p5, angle_p5, 12, accentColorUp)}
            </>
          )}
        </svg>

        {/* Dynamic HTML Annotations Layer */}
        
        {/* "Strong move up" Pill */}
        <div
          style={{
            position: "absolute",
            left: "19%",
            top: "60%",
            opacity: interpolate(p1Progress, [0.4, 0.95], [0, 1], { extrapolateRight: "clamp" }),
            border: `1px solid ${accentColorUp}77`,
            borderRadius: "6px",
            backgroundColor: `${accentColorUp}12`,
            padding: "6px 14px",
            color: accentColorUp,
            fontWeight: "bold",
            fontSize: `${Math.min(width, height) * 0.014}px`,
            boxShadow: `0 0 12px ${accentColorUp}15`,
            transition: "none",
            zIndex: 4,
          }}
        >
          {strongMoveLabel}
        </div>

        {/* FOMO Entry Indicator Circle */}
        {frame >= p2Start && (
          <div
            style={{
              position: "absolute",
              left: "39.5%",
              top: "28.5%",
              width: "16px",
              height: "16px",
              borderRadius: "50%",
              backgroundColor: accentColorEntry,
              transform: `translate(-50%, -50%) scale(${p2Spring})`,
              boxShadow: `0 0 15px ${accentColorEntry}`,
              zIndex: 5,
              transition: "none",
            }}
          />
        )}

        {/* "FOMO Buy — enters late" yellow text */}
        <div
          style={{
            position: "absolute",
            left: "26.5%",
            top: "12%",
            transform: `scale(${p2Spring})`,
            transformOrigin: "right bottom",
            opacity: p2Progress,
            color: accentColorEntry,
            fontSize: `${Math.min(width, height) * 0.014}px`,
            fontWeight: "bold",
            textAlign: "right",
            lineHeight: 1.25,
            transition: "none",
            zIndex: 4,
          }}
        >
          <div>{fomoLabel.split(" — ")[0]} —</div>
          <div style={{ opacity: 0.85, fontWeight: "normal" }}>{fomoLabel.split(" — ")[1]}</div>
        </div>

        {/* Left Stop Loss Pill */}
        {leftPillVisible && (
          <div
            style={{
              position: "absolute",
              left: "1.5%",
              top: "74.8%",
              border: `1px solid ${stopColor}`,
              borderRadius: "6px",
              backgroundColor: "#080b0e",
              padding: "4px 10px",
              color: stopColor,
              fontWeight: "bold",
              fontSize: `${Math.min(width, height) * 0.012}px`,
              boxShadow: flashActive && flashPhase ? `0 0 15px ${accentColorDown}` : "none",
              textShadow: stopTextShadow,
              transition: "none",
              zIndex: 5,
            }}
          >
            {stopLossLabel}
          </div>
        )}

        {/* Right Stop Loss Pill */}
        {rightPillVisible && (
          <div
            style={{
              position: "absolute",
              right: "1.5%",
              top: "74.8%",
              border: `1px solid ${stopColor}`,
              borderRadius: "6px",
              backgroundColor: "#080b0e",
              padding: "4px 10px",
              color: stopColor,
              fontWeight: "bold",
              fontSize: `${Math.min(width, height) * 0.012}px`,
              boxShadow: flashActive && flashPhase ? `0 0 15px ${accentColorDown}` : "none",
              textShadow: stopTextShadow,
              transition: "none",
              zIndex: 5,
            }}
          >
            {stopLossLabel}
          </div>
        )}

        {/* Kinetic Hit Spark Bloom at Stop Loss level */}
        {frame >= p4Start && frame <= p4Start + 18 && (
          <div
            style={{
              position: "absolute",
              left: "61%",
              top: "78%",
              width: "50px",
              height: "50px",
              borderRadius: "50%",
              background: "radial-gradient(circle, #ffffff 0%, rgba(239,83,80,0.9) 40%, transparent 100%)",
              transform: `translate(-50%, -50%) scale(${interpolate(frame - p4Start, [0, 18], [0.3, 3], { extrapolateRight: "clamp" })})`,
              opacity: interpolate(frame - p4Start, [0, 18], [1, 0], { extrapolateRight: "clamp" }),
              pointerEvents: "none",
              zIndex: 10,
              transition: "none",
            }}
          />
        )}

        {/* STOPPED OUT Alert Display */}
        <div
          style={{
            position: "absolute",
            left: "53%",
            top: "81%",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            opacity: p4Progress,
            transform: `scale(${stoppedOutScale})`,
            transition: "none",
            zIndex: 6,
          }}
        >
          {/* Red Pulse Cross Icon */}
          <div
            style={{
              width: `${Math.min(width, height) * 0.035}px`,
              height: `${Math.min(width, height) * 0.035}px`,
              borderRadius: "50%",
              backgroundColor: accentColorDown,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: `0 0 15px ${accentColorDown}`,
              marginBottom: "8px",
            }}
          >
            <svg width="60%" height="60%" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round">
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </div>
          {/* Label */}
          <span
            style={{
              color: accentColorDown,
              fontWeight: "900",
              fontSize: `${Math.min(width, height) * 0.015}px`,
              letterSpacing: "1px",
              textShadow: `0 0 10px ${accentColorDown}55`,
            }}
          >
            STOPPED OUT
          </span>
        </div>

        {/* "Price continues without you" Pill */}
        <div
          style={{
            position: "absolute",
            left: "81%",
            top: "56%",
            opacity: p5Progress,
            transform: `scale(${spring({ frame: frame - p5Start, fps, config: { damping: 12 } })})`,
            border: `1px solid ${accentColorUp}77`,
            borderRadius: "6px",
            backgroundColor: `${accentColorUp}12`,
            padding: "8px 14px",
            color: accentColorUp,
            fontWeight: "bold",
            fontSize: `${Math.min(width, height) * 0.013}px`,
            boxShadow: `0 0 12px ${accentColorUp}15`,
            transition: "none",
            maxWidth: "180px",
            textAlign: "center",
            zIndex: 4,
          }}
        >
          {reversalLabel}
        </div>
      </div>

      {/* Narrative Caption Bar at Bottom */}
      <div
        style={{
          position: "absolute",
          bottom: `${height * 0.04}px`,
          left: "50%",
          transform: `translate(-50%, ${interpolate(p6Progress, [0, 1], [15, 0], { extrapolateRight: "clamp" })}px)`,
          width: "90%",
          maxWidth: "1000px",
          backgroundColor: "rgba(10, 14, 18, 0.9)",
          border: "1px solid rgba(255, 255, 255, 0.06)",
          borderRadius: "12px",
          padding: `${height * 0.018}px ${width * 0.03}px`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          boxShadow: "0 10px 30px rgba(0, 0, 0, 0.6)",
          opacity: p6Progress,
          transition: "none",
          zIndex: 10,
          boxSizing: "border-box",
        }}
      >
        <span
          style={{
            color: "#ffffff",
            fontSize: `${Math.min(width, height) * 0.024}px`,
            fontWeight: "500",
            textAlign: "center",
            letterSpacing: "0.2px",
          }}
        >
          {firstCaptionPart}{" "}
          <span style={{ color: accentColorDown, fontWeight: "bold" }}>
            {secondCaptionPart}
          </span>
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default TerminalTradingChart;